*{box-sizing:border-box} :root{--ink:#d8d1c2;--muted:#85867f;--faint:#545852;--panel:#171a18;--line:#303531;--gold:#bd9a63;--red:#bd655b;--green:#94a58a} html,body{height:100%;margin:0;background:#101211;color:var(--ink);font-family:'DM Sans',sans-serif}body{overflow:hidden}.game-shell{height:100%;min-height:580px;max-width:1800px;margin:auto;padding:0 27px 22px;display:flex;flex-direction:column}.topbar{height:83px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #2b302d;flex-shrink:0}.brand{display:flex;align-items:center;gap:14px}.sigil{width:37px;height:37px;border:1px solid #826b49;color:var(--gold);display:grid;place-items:center;font-size:21px;transform:rotate(45deg);margin:0 4px}.sigil::first-letter{transform:rotate(-45deg)}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.55px;color:#8d8c81}.brand h1{font:600 16px 'Playfair Display',serif;letter-spacing:1.2px;margin:4px 0 0}.brand h1 span{color:#8b7454;font-size:12px;padding:0 3px}.top-meta{display:flex;align-items:center;gap:25px}.weather{font:10px 'DM Mono',monospace;color:#9da29b;letter-spacing:1px}.weather-icon{color:#8393a2;font-size:17px;margin-right:6px}.day-stamp{display:flex;flex-direction:column;gap:3px;border-left:1px solid var(--line);padding-left:20px;font:10px 'DM Mono',monospace;color:#898c86}.day-stamp b{font-size:15px;color:#d4cbb8;font-weight:400}.icon-button,.dots{border:1px solid #383d39;background:transparent;color:#a8a99f;width:34px;height:32px;cursor:pointer}.icon-button:hover,.dots:hover{border-color:var(--gold);color:var(--gold)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 326px;gap:19px;flex:1;min-height:0;padding-top:18px}.world-column{min-height:0;display:flex;flex-direction:column}.scene-wrap{position:relative;overflow:hidden;flex:1;min-height:300px;background:#1a2220;border:1px solid #383b35;box-shadow:0 14px 40px #0005}.scene-wrap canvas{display:block;width:100%;height:100%;image-rendering:auto}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#0b0f0d9c 0%,transparent 25%,transparent 72%,#0b0e0de0 100%),radial-gradient(ellipse at center,transparent 30%,#0609088c 100%);box-shadow:inset 0 0 0 1px #ffffff08}.scene-heading{position:absolute;left:22px;top:18px;color:#c0bcad;font:10px 'DM Mono',monospace;letter-spacing:1.4px;display:flex;align-items:center;gap:9px;text-shadow:0 1px #000}.live-dot{height:6px;width:6px;border-radius:50%;background:#a96e5c;box-shadow:0 0 9px #bd655b}.scene-coordinates{position:absolute;right:21px;top:18px;color:#9c9e94;font:9px 'DM Mono',monospace;letter-spacing:1px}.scene-bottom{position:absolute;bottom:0;left:0;right:0;display:flex;justify-content:space-between;align-items:end;padding:22px 23px 18px}.objective{display:flex;align-items:center;gap:12px}.objective-mark{color:var(--gold);font-size:19px}.objective small,.objective strong{display:block}.objective small{font:9px 'DM Mono',monospace;color:#99968a;letter-spacing:1.4px;margin-bottom:4px}.objective strong{font:500 14px 'Playfair Display',serif;color:#e3ddcf}.world-controls{display:flex;gap:14px;font:10px 'DM Mono',monospace;color:#d0cbbc}.world-controls i{font-style:normal;color:#86877f;font-size:8px;margin-left:4px}.interact-prompt{position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);background:#111613e8;border:1px solid #9a8055;padding:9px 14px;color:#ddd5c5;font:10px 'DM Mono',monospace;letter-spacing:1px;display:flex;align-items:center;gap:9px;white-space:nowrap;box-shadow:0 3px 20px #0008;pointer-events:none}.interact-prompt span{border:1px solid #786848;color:var(--gold);padding:3px 6px}.hidden{display:none!important}.rain-layer{position:absolute;inset:0;pointer-events:none;opacity:.32;background:repeating-linear-gradient(105deg,transparent 0 39px,#9caeb30e 40px,#bbc8cc15 41px,transparent 42px 75px);animation:rain 1.4s linear infinite}@keyframes rain{to{background-position:0 70px}}.footbar{height:77px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;border:1px solid #303531;border-top:0;background:#161917;padding:0 15px}.player-readout{display:flex;align-items:center;gap:10px;min-width:220px}.portrait{width:34px;height:34px;border:1px solid #646256;background:linear-gradient(145deg,#454942,#222722);display:grid;place-items:center;color:#c9b991;font:600 17px 'Playfair Display',serif}.player-readout strong,.player-readout small{display:block}.player-readout strong{font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#c8c3b4}.player-readout small{font:8px 'DM Mono',monospace;letter-spacing:.8px;color:#777b73;margin-top:5px}.vitals{display:flex;gap:19px}.vital{display:grid;grid-template-columns:auto 70px auto;align-items:center;gap:7px}.vital span{font:8px 'DM Mono',monospace;color:#8d8e85;letter-spacing:.6px}.vital b{font:9px 'DM Mono',monospace;color:#b8b4a7;font-weight:400}.meter{height:3px;background:#333833;width:66px}.meter i{height:100%;display:block;width:94%;background:#93a187}.meter.sanity i{background:#a28762}.meter.fatigue i{background:#748894}.foot-actions{display:flex;gap:8px}.small-button{background:#202420;border:1px solid #3a4039;color:#b8b5a8;padding:8px 10px;cursor:pointer;font-size:12px}.small-button:hover{border-color:#90764f}.small-button span{font:8px 'DM Mono',monospace;letter-spacing:1px;margin-left:3px}.case-sidebar{background:#171a18;border:1px solid #303531;display:flex;flex-direction:column;min-height:0}.case-head{padding:21px 19px 14px;display:flex;justify-content:space-between;align-items:center}.case-head .eyebrow{font-size:9px;letter-spacing:1.1px}.case-id{color:#88724f;margin-left:5px}.case-head h2{font:600 21px 'Playfair Display',serif;margin:6px 0 0;color:#e1dbcd}.dots{border:0;letter-spacing:2px}.case-summary{padding:0 19px 15px;border-bottom:1px solid var(--line)}.case-summary p{margin:0 0 17px;color:#a6a69c;font:12px/1.55 'DM Sans',sans-serif;max-width:270px}.case-stats{display:flex;gap:24px}.case-stats div{display:flex;align-items:baseline;gap:5px}.case-stats strong{font:15px 'DM Mono',monospace;color:#d5c7aa;font-weight:400}.case-stats span{font:8px 'DM Mono',monospace;color:#85877e;letter-spacing:.4px}.sidebar-section{padding:15px 19px 8px}.section-title{font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#9b9b90;margin-bottom:10px;display:flex;align-items:center;gap:8px}.section-count{color:#77796f;border:1px solid #343934;padding:2px 5px;font-size:8px}.lead-card{width:100%;display:flex;align-items:center;text-align:left;background:transparent;border:1px solid transparent;color:#cbc7b9;padding:7px 5px;margin:1px 0;gap:10px;cursor:pointer}.lead-card:hover,.lead-card.active{background:#202420;border-color:#393d36}.lead-icon{width:25px;height:25px;display:grid;place-items:center;border:1px solid #51463b;color:#bd9161;font-size:13px;flex-shrink:0}.lead-icon.witness{color:#8c9a8b;border-color:#414c43}.lead-icon.symbol{color:#9e8f74;border-color:#4b4539}.lead-card span:nth-child(2){flex:1}.lead-card b,.lead-card small{display:block}.lead-card b{font:500 11px 'DM Sans',sans-serif}.lead-card small{font:9px 'DM Sans',sans-serif;color:#888b82;margin-top:4px}.lead-arrow{color:#817960;font-size:12px}.people-section{border-top:1px solid var(--line);margin-top:7px;padding-top:14px}.person-row{display:flex;align-items:center;width:100%;text-align:left;background:none;border:0;color:#d1ccbe;padding:5px 0;gap:9px;cursor:pointer}.person-row:hover .person-info b{color:var(--gold)}.person-avatar{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font:9px 'DM Mono',monospace;color:#ddd1bb;border:1px solid #756858;background:#37332e}.avatar-two{background:#2e3633;border-color:#58645a}.avatar-unknown{color:#aa8c68;background:#292722;border-color:#6d604d}.person-info{flex:1}.person-info b,.person-info small{display:block}.person-info b{font-size:10px;font-weight:500}.person-info small{font-size:9px;color:#85877f;margin-top:3px}.suspicion{height:3px;width:28px;background:#383b35}.suspicion i{height:100%;display:block;width:var(--level);background:#ab7459}.pressure-section{border-top:1px solid var(--line);margin-top:7px;padding-top:14px}.pulse-live{color:#80927f;font-size:8px;border:1px solid #414a3f;padding:2px 5px}.pulse-card{position:relative;padding:11px 11px 10px 31px;background:#1c211d;border:1px solid #333a33}.pulse-glyph{position:absolute;left:11px;top:11px;color:#ae9469;font-size:14px}.pulse-card p{font:10px/1.45 'DM Sans',sans-serif;color:#b9b8ac;margin:0 0 9px}.pulse-card small{font:8px 'DM Mono',monospace;color:#777d74;letter-spacing:.5px}.sidebar-bottom{margin-top:auto;border-top:1px solid var(--line);padding:12px 18px;display:flex;flex-direction:column;gap:10px}.sidebar-bottom>span{font:8px 'DM Mono',monospace;color:#716f63;letter-spacing:1.3px}.sidebar-bottom button{background:#282821;border:1px solid #60543f;padding:10px;color:#dbceb4;text-align:left;font:9px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.sidebar-bottom button:hover{background:#353328}.sidebar-bottom button b{font-size:8px;border:1px solid #756849;padding:3px 5px;margin-left:8px;color:#c5ab7c}.sidebar-bottom button span{float:right;color:#9f8961}.mobile-nav{display:none}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);background:#1b201c;border:1px solid #85704b;padding:11px 16px;color:#e0d5bd;font:11px 'DM Mono',monospace;letter-spacing:.4px;opacity:0;transition:.25s;z-index:20;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
/* investigation panels */
.modal-backdrop{position:fixed;inset:0;background:#080b09c9;z-index:30;display:grid;place-items:center;padding:20px;backdrop-filter:blur(4px)}.modal{background:#171b18;border:1px solid #4a4b40;width:min(760px,100%);max-height:min(700px,92vh);overflow:auto;box-shadow:0 24px 90px #000b}.modal-top{padding:20px 24px 15px;border-bottom:1px solid #373b35;display:flex;justify-content:space-between;align-items:start}.modal-top .eyebrow{font-size:9px}.modal-top h2{font:600 25px 'Playfair Display',serif;margin:6px 0 0;color:#e1dbce}.close-modal{background:none;border:1px solid #41453e;color:#b4b1a5;width:29px;height:29px;cursor:pointer}.modal-body{padding:20px 24px 25px;color:#b9baaf;font:13px/1.65 'DM Sans',sans-serif}.modal-body p{margin:0 0 14px}.modal-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:19px}.action-button{background:#272c27;color:#ddd4c1;border:1px solid #5b584a;padding:10px 13px;font:10px 'DM Mono',monospace;letter-spacing:.5px;cursor:pointer}.action-button:hover{background:#34382f;border-color:#aa8a5d}.action-button.primary{background:#605039;border-color:#997d53;color:#f0e2c6}.action-button.danger{border-color:#85544b;color:#d59c8d}.dialogue-line{border-left:2px solid #927952;padding:8px 0 8px 14px;margin:13px 0;color:#d1c7b1;font:italic 15px 'Playfair Display',serif}.evidence-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:15px}.evidence-item{background:#202521;border:1px solid #3c423b;padding:12px}.evidence-item b{display:block;font:10px 'DM Mono',monospace;letter-spacing:.5px;color:#d0c3a6}.evidence-item small{display:block;color:#92958b;font-size:10px;line-height:1.45;margin-top:6px}.tag{display:inline-block;color:#83917e;border:1px solid #495446;padding:2px 5px;font:8px 'DM Mono',monospace;letter-spacing:.5px;margin-top:8px}.tag.unverified{color:#ae9271;border-color:#5b4b3b}.tab-row{display:flex;border-bottom:1px solid #3b4039;margin:0 24px}.tab-button{background:none;border:0;color:#8f9188;font:9px 'DM Mono',monospace;letter-spacing:1px;padding:12px 14px;cursor:pointer}.tab-button.selected{color:#d8c8a9;border-bottom:1px solid var(--gold)}.clue-row{display:flex;align-items:center;gap:12px;border-bottom:1px solid #333833;padding:11px 0}.clue-row input{accent-color:#a88b5d;width:15px;height:15px}.clue-row b{display:block;font-size:11px;color:#ddd4c4}.clue-row small{display:block;color:#858981;font-size:10px}.note-area{width:100%;min-height:100px;background:#202420;border:1px solid #454a42;color:#ddd5c6;padding:12px;font:12px/1.5 'DM Sans',sans-serif;resize:vertical}.board{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.board .evidence-item{min-height:82px}.map-legend{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:12px}.map-place{background:#202521;border:1px solid #394038;text-align:left;color:#c9c4b8;padding:11px;cursor:pointer;font-size:11px}.map-place small{display:block;color:#8c9086;margin-top:4px}.event-log{border-left:1px solid #57533f;margin-left:5px;padding-left:17px}.event-log article{position:relative;margin:0 0 17px}.event-log article:before{content:'';position:absolute;left:-21px;top:5px;width:7px;height:7px;background:#a58a5c;border-radius:50%}.event-log small{display:block;color:#8e8f85;font:9px 'DM Mono',monospace}.event-log b{display:block;color:#d4c9b4;font-size:12px;margin:3px 0}.event-log p{font-size:11px;margin:0;color:#9ea096}.outcome{font:600 27px 'Playfair Display',serif;color:#d6c6a5;margin-bottom:10px}.subtle{font-size:11px;color:#92958b}.statusline{font:9px 'DM Mono',monospace;letter-spacing:.6px;color:#9c8b69;margin:10px 0}.person-details{display:flex;gap:14px;align-items:center;margin-bottom:15px}.person-details .person-avatar{width:47px;height:47px;font-size:13px}.person-details h3{margin:0;color:#e0d7c6;font:18px 'Playfair Display',serif}.person-details small{color:#98998f;font:10px 'DM Mono',monospace}.audio-pulse{height:14px;width:70px;display:flex;gap:3px;align-items:center}.audio-pulse i{height:5px;width:2px;background:#a98d61;animation:wave .5s ease-in-out infinite alternate}.audio-pulse i:nth-child(2n){animation-delay:.2s}.audio-pulse i:nth-child(3n){animation-delay:.35s}@keyframes wave{to{height:13px}}
@media(max-width:1050px){.game-shell{padding:0 15px 15px}.game-layout{grid-template-columns:minmax(0,1fr) 290px;gap:12px}.case-head{padding:16px 14px 12px}.case-summary,.sidebar-section{padding-left:14px;padding-right:14px}.sidebar-bottom{padding:11px 14px}.vitals{gap:10px}.vital{grid-template-columns:auto 46px auto;gap:5px}.meter{width:45px}.player-readout{min-width:170px}.world-controls{gap:8px}.world-controls span{font-size:9px}}
@media(max-width:760px){body{overflow:auto}.game-shell{height:100dvh;min-height:630px;padding:0 10px 8px}.topbar{height:67px}.brand{gap:9px}.sigil{height:30px;width:30px;font-size:17px}.brand .eyebrow{font-size:8px;letter-spacing:.8px}.brand h1{font-size:12px;letter-spacing:.4px}.top-meta{gap:9px}.weather{display:none}.day-stamp{padding-left:9px}.icon-button{width:29px;height:29px}.game-layout{display:block;padding-top:9px;min-height:0}.world-column{height:calc(100% - 1px)}.scene-wrap{min-height:330px}.footbar{height:66px;padding:0 9px}.player-readout{min-width:0}.player-readout strong{font-size:8px}.player-readout small{font-size:7px}.portrait{width:29px;height:29px}.vitals{gap:7px}.vital{display:flex;flex-direction:column;gap:3px;align-items:flex-start}.vital span{font-size:7px}.vital b{display:none}.meter{width:40px;height:3px}.foot-actions{display:none}.world-controls{gap:7px}.world-controls span{font-size:8px}.world-controls i{font-size:7px}.scene-bottom{padding:14px 12px}.objective strong{font-size:12px}.objective small{font-size:8px}.scene-heading{left:12px;top:13px;font-size:8px}.scene-coordinates{right:12px;top:13px;font-size:8px}.case-sidebar{display:none}.mobile-nav{position:absolute;display:flex;left:10px;right:10px;bottom:8px;justify-content:center;gap:7px;pointer-events:none}.mobile-nav button{pointer-events:auto;background:#202420e8;border:1px solid #555344;color:#cfc5b0;padding:8px 13px;font:9px 'DM Mono',monospace;letter-spacing:1px}.game-shell{padding-bottom:43px}.modal{max-height:88vh}.modal-top{padding:16px 17px 12px}.modal-body{padding:15px 17px 20px}.modal-top h2{font-size:22px}.tab-row{margin:0 17px}.tab-button{padding:10px 9px;font-size:8px}.evidence-list{grid-template-columns:1fr}.board{grid-template-columns:1fr 1fr}.mobile-nav{bottom:8px}}

(() => {
  'use strict';
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const W = 1600, H = 1100, $ = id => document.getElementById(id);
  const places = [
    {id:'scene',name:"ST. ORAN'S BELL TOWER",sub:'CRIME SCENE · CORDON ACTIVE',x:410,y:365,color:'#6b5144',kind:'scene',icon:'✳'},
    {id:'diner',name:'THE LANTERN DINER',sub:'WITNESS LAST SEEN HERE',x:740,y:535,color:'#76634d',kind:'diner',icon:'▰'},
    {id:'church',name:'ST. ORAN PARISH',sub:'PARISH ARCHIVES · OPEN',x:700,y:250,color:'#746d5c',kind:'church',icon:'✝'},
    {id:'precinct',name:'BELLWETHER PRECINCT',sub:'MAJOR CRIMES · YOUR OFFICE',x:1085,y:350,color:'#51605a',kind:'precinct',icon:'▥'},
    {id:'morgue',name:'COUNTY MEDICAL EXAMINER',sub:'AUTOPSY WING · RESTRICTED',x:1160,y:685,color:'#53615a',kind:'morgue',icon:'＋'},
    {id:'cemetery',name:'ASHGROVE CEMETERY',sub:'NORTH GATE · 24 HOURS',x:260,y:750,color:'#596450',kind:'cemetery',icon:'†'},
    {id:'archive',name:'OLD COUNTY RECORDS',sub:'BASEMENT STACKS',x:900,y:800,color:'#625c50',kind:'archive',icon:'▤'},
    {id:'apartment',name:'VANE STREET FLATS',sub:'MISSING PERSONS ADDRESS',x:1330,y:510,color:'#69584f',kind:'apartment',icon:'▥'},
    {id:'forest',name:'BLACKWATER TREE LINE',sub:'COUNTY ROAD 9 · NO LIGHTING',x:360,y:990,color:'#465443',kind:'forest',icon:'♧'},
    {id:'bar',name:'THE MERCY ROOM',sub:'CLOSED FOR THE NIGHT',x:950,y:170,color:'#594c48',kind:'bar',icon:'◒'},
    {id:'hospital',name:'BELLWETHER GENERAL',sub:'EMERGENCY DEPARTMENT',x:1400,y:850,color:'#52605e',kind:'hospital',icon:'＋'}
  ];
  const seed = n => {let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
  const npcNames=['Mara Venn','Silas Crowe','Ruth Bell','Jonah Pike','Elise Ward','Tom Arlen','Nora Vale','Caleb Dunn','Miriam Holt','Edwin Shaw','June Mercer','Isaac Reed','Lena Park','Peter Moss','Ada Finch','Gideon Frost'];
  const npcs=Array.from({length:42},(_,i)=>({id:i,name:npcNames[i%npcNames.length]+(i>=16?' '+String.fromCharCode(65+i%26):''),x:90+seed(i+4)*1420,y:90+seed(i+90)*920,home:places[Math.floor(seed(i+500)*places.length)].id,mood:seed(i+100)*2-1,phase:seed(i+120)*Math.PI*2,speed:.15+seed(i+40)*.28,important:i===1||i===2||i===3,alive:true}));
  const defaults=()=>({version:1,day:1,minute:21*60+14,weather:'COLD RAIN',player:{x:455,y:385,health:94,stress:28,fatigue:18},evidence:[],notes:'',events:[{day:1,time:'21:14',title:'A bell after the storm',text:'Patrol found Mara Venn beneath the bell tower at St. Oran’s. The scene was secured at 20:46.'}],interviews:{},visited:{},warrant:false,arrested:false,sect:0,public:0,adapt:0,visits:{},killerrisk:18, killerMood:'observant',killerRoutine:'parish',randomSeed:Math.floor(Math.random()*1e8),flags:{},npcMemory:{},theories:[],heardBell:true,ending:null});
  let S=loadAuto()||defaults(), cam={x:0,y:0}, keys={},lastTick=performance.now(),acc=0,toastTimer,modalPage='overview',activePlace=null,moveEnabled=true,wasMoving=false,ambientOn=false;
  const evidenceData={
    sigil:{name:'The split halo',kind:'VERIFIED · SCENE',desc:'A hand-drawn mark in ash beneath the bell stairs. The upper arc is deliberately broken. Not a standard parish symbol.'},
    fiber:{name:'Gray wool fiber',kind:'LAB · TRACE',desc:'A coarse gray wool fiber snagged on a nail at shoulder height. Consistent with a heavy coat; common in town, but not the scene custodians’ uniforms.'},
    token:{name:'Brass choir token',kind:'VERIFIED · SCENE',desc:'A tarnished token stamped with nine small notches. Parish ledgers call these “attendance counters”; the ninth notch is newer.'},
    witness:{name:'A voice at 9:13',kind:'WITNESS · UNCORROBORATED',desc:'Diner cook Jonah Pike remembers a calm voice asking whether the tower door still sticks. He recalls a smell of clove and wet wool.'},
    ledger:{name:'The Ninth Verse',kind:'DOCUMENT · VERIFIED',desc:'A marginal note in a 1938 hymn ledger: “When the bell speaks without a hand, the keeper must answer.” Initials S.C. appear in the same ink.'},
    autopsy:{name:'Estimated time of death',kind:'FORENSIC · VERIFIED',desc:'Dr. Vale places death between 19:40 and 20:20. The staged scene was assembled later; the arrangement is not a reliable signature.'},
    register:{name:'Restricted choir register',kind:'DOCUMENT · LEAD',desc:'An old roll lists nine “night keepers.” One line was cut out; the ledger was signed out under Silas Crowe’s credentials last month.'},
    letter:{name:'Unsent letter',kind:'PERSONAL · UNVERIFIED',desc:'A letter in Mara’s flat mentions “the ones who wear ordinary faces” and asks someone to stop coming to the archives.'}
  };
  function loadAuto(){try{return JSON.parse(localStorage.getItem('town-autosave')||'null')}catch{return null}}
  function save(slot='auto'){try{localStorage.setItem('town-'+slot,JSON.stringify(S)); if(slot!=='auto')toast(`CASE FILE SAVED · SLOT ${slot.replace('slot','')}`); else toast('AUTOSAVE COMPLETE')}catch{toast('SAVE FAILED · STORAGE UNAVAILABLE')}}
  function addEvidence(id){if(S.evidence.includes(id)){toast('ALREADY LOGGED · CHAIN OF CUSTODY INTACT');return false}S.evidence.push(id);S.events.unshift({day:S.day,time:clock(),title:`Evidence logged: ${evidenceData[id].name}`,text:evidenceData[id].desc});updateUI();save('auto');return true}
  function log(title,text){S.events.unshift({day:S.day,time:clock(),title,text});S.events=S.events.slice(0,40)}
  function clock(){return String(Math.floor(S.minute/60)%24).padStart(2,'0')+':'+String(S.minute%60).padStart(2,'0')}
