function sceneModal(){const found=['sigil','fiber','token'].filter(x=>!S.evidence.includes(x));const actions=found.map(id=>({label:'COLLECT · '+evidenceData[id].name.toUpperCase(),run:()=>{addEvidence(id);closeModal();sceneModal()}}));actions.push({label:'PHOTOGRAPH SCENE',run:()=>{S.flags.scenePhoto=true;log('Scene documented','Wide, mid-range, and detail photographs added to the case file.');toast('SCENE PHOTOGRAPHED · EVIDENCE PRESERVED');advance(12);closeModal()}});actions.push({label:'LEAVE SCENE',run:closeModal});openModal("St. Oran's bell tower",'CRIME SCENE · SECURED 20:46',`<p>The tower smells of wet stone and old incense. A strip of yellow tape moves in the wind. The body has been removed; what remains is an unnerving arrangement of chalk, ash, and one unlit votive.</p><div class="statusline">CHAIN OF CUSTODY ACTIVE · ${S.evidence.filter(x=>['sigil','fiber','token'].includes(x)).length}/3 OBSERVATIONS LOGGED</div><div class="evidence-list">${['sigil','fiber','token'].map(id=>`<div class="evidence-item"><b>${evidenceData[id].name}</b><small>${S.evidence.includes(id)?'Logged in evidence inventory.':evidenceData[id].desc}</small><span class="tag ${S.evidence.includes(id)?'':'unverified'}">${S.evidence.includes(id)?'COLLECTED':'AVAILABLE TO EXAMINE'}</span></div>`).join('')}</div>`,actions)}
