  function morgueModal(){const actions=[];if(!S.evidence.includes('autopsy'))actions.push({label:'REQUEST PRELIMINARY AUTOPSY',kind:'primary',run:()=>{addEvidence('autopsy');advance(28,'morgue');log('Medical examiner consulted','Dr. Nora Vale estimates death between 19:40 and 20:20. The staged arrangement happened after death.');openModal('Dr. Nora Vale','COUNTY MEDICAL EXAMINER',`<p>Dr. Vale turns a page in the preliminary report. There are no reliable injuries pointing to a ritual. The estimate is broad, but places the death before the scene was arranged.</p><div class="statusline">FORENSIC REPORT · ESTIMATED WINDOW 19:40–20:20</div><p class="subtle">Cause of death is pending full toxicology. A precise time cannot be claimed yet.</p>`,[{label:'THANK THE DOCTOR',run:closeModal}])}});else actions.push({label:'ASK ABOUT TOXICOLOGY',run:()=>{S.flags.toxAsked=true;advance(12);openModal('Pending toxicology','MEDICAL EXAMINER · FOLLOW-UP',`<p>The lab has not found a result that changes the initial assessment. Dr. Vale cautions that the sample is degraded and should not be used to identify a suspect.</p><div class="statusline">NO NEW FORENSIC CONCLUSION</div>`,[{label:'RETURN',run:closeModal}])}});actions.push({label:'LEAVE',run:closeModal});openModal('County Medical Examiner','AUTOPSY WING · RESTRICTED',`<p>The corridor hums with old fluorescent lights. Dr. Nora Vale has agreed to share the preliminary report, but asks that uncertainty be preserved in every copy.</p><div class="statusline">DECEDENT: MARA VENN · REPORT STATUS: ${S.evidence.includes('autopsy')?'PRELIMINARY FILED':'AVAILABLE'}</div>`,actions)}
  function archiveModal(){const actions=[];if(!S.evidence.includes('letter'))actions.push({label:'CHECK ARCHIVE ACCESS LOG',run:()=>{S.flags.archiveLog=true;advance(16);openModal('A gap in the sign-out book','OLD COUNTY RECORDS · BASEMENT',`<p>The archive log shows Mara Venn visited twice in the week before her death. The relevant folder was returned, but a page is missing from the sign-in ledger. No one recalls who removed it.</p><p class="subtle">A lead, not proof of an accomplice or a secret organization.</p><div class="statusline">ACCESS LOG PRESERVED · NO PERSON IDENTIFIED</div>`,[{label:'FILE THE LEAD',run:()=>{log('Archive access log checked','Mara visited the county records office twice. A page is missing, but the removal cannot be attributed.');closeModal()}}])}});actions.push({label:'LEAVE',run:closeModal});openModal('Old County Records','BASEMENT STACKS · 22:06',`<p>Dust settles over municipal ledgers and flood-damaged parish boxes. A clerk remembers Mara asking about property transfers and the original choir register.</p><div class="statusline">ARCHIVE ACCESS REQUIRES A CLERK’S LOG</div>`,actions)}
