  function cemeteryModal(){const actions=[{label:'CHECK THE VENN FAMILY PLOT',run:()=>{S.player.stress=Math.min(100,S.player.stress+5);advance(18);openModal('Names beneath the rain','ASHGROVE CEMETERY · VENN PLOT',`<p>Mara’s mother is buried here. A fresh candle sits at the headstone, sheltered in a jar. There is no note and no useful print in the rain.</p><p class="subtle">For a moment, a bell seems to answer from beyond the tree line. No one else reacts.</p>`,[{label:'STEP AWAY',run:closeModal}])}},{label:'REST AT THE GATE',run:()=>{S.player.stress=Math.max(0,S.player.stress-7);advance(25);closeModal();toast('A QUIET MOMENT · COMPOSURE RECOVERED')}},{label:'LEAVE',run:closeModal}];openModal('Ashgrove Cemetery','NORTH GATE · 24 HOURS',`<p>Rows of stones fade into the wet dark. The cemetery keeper has gone home; the gate is not locked.</p><div class="statusline">WEATHER: ${S.weather} · TIME: ${clock()}</div>`,actions)}

