    if(modalPage==='timeline')body=`<div class="event-list">${S.events.map(e=>`<article><b>DAY ${String(e.day).padStart(2,'0')} · ${e.time}</b><strong>${e.title}</strong><p>${e.text}</p></article>`).join('')||'<p>No events recorded.</p>'}</div>`;
