    const root=$('modalRoot');root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>caseFile(b.dataset.tab));root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save('slot'+b.dataset.save));root.querySelectorAll('[data-load]').forEach(b=>b.onclick=()=>loadSlot(b.dataset.load));const newBtn=$('newCaseBtn');if(newBtn)newBtn.onclick=()=>{if(confirm('Start a new case? Current progress remains in autosave, but unsaved changes in this slot may be lost.')){S=defaults();save('auto');closeModal();updateUI();toast('NEW CASE OPENED')}}
  }
  function loadSlot(slot){try{const data=JSON.parse(localStorage.getItem('town-slot'+slot)||'null');if(!data){toast('SLOT EMPTY');return}S=Object.assign(defaults(),data);S.player=Object.assign(defaults().player,data.player||{});S.flags=Object.assign({},data.flags||{});S.evidence=Array.isArray(data.evidence)?data.evidence:[];closeModal();updateUI();save('auto');toast('CASE FILE LOADED · SLOT '+slot)}catch{toast('LOAD FAILED · FILE COULD NOT BE READ')}}
  function rest(){if(moveEnabled){S.player.health=Math.min(100,S.player.health+10);S.player.stress=Math.max(0,S.player.stress-12);S.player.fatigue=Math.max(0,S.player.fatigue-28);advance(90,'rest');log('Rested between shifts','A few hours of sleep restored some health and composure. The town kept moving.');toast('RESTED · 90 MINUTES PASSED')}}
  function toggleSound(){ambientOn=!ambientOn;$('soundBtn').classList.toggle('active',ambientOn);if(ambientOn){try{const AC=window.AudioContext||window.webkitAudioContext;if(AC){const audio=new AC(),osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=48;gain.gain.value=.018;osc.connect(gain);gain.connect(audio.destination);osc.start();ambient={audio,osc,gain};}}catch{}toast('LOW AMBIENCE ON')}else{if(ambient){ambient.gain.gain.setTargetAtTime(0,ambient.audio.currentTime,.12);ambient.osc.stop(ambient.audio.currentTime+.4);ambient.audio.close();ambient=null}toast('AMBIENCE OFF')}}
  let ambient=null;
  function interact(){if(!moveEnabled)return;const p=activeNear();if(p){routeTarget=null;actPlace(p)}}
  function gotoPlace(id){const p=places.find(x=>x.id===id);if(!p)return;routeTarget={x:p.x,y:p.y};toast('ROUTE SET · '+p.name)}
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','q','e'].includes(k))e.preventDefault();if(k==='escape'){if($('modalRoot').innerHTML)closeModal();else routeTarget=null;return}if(k==='e'){interact();return}if(k==='q'){if(moveEnabled)caseFile('overview');return}if(!moveEnabled)return;keys[k]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});window.addEventListener('blur',()=>{keys={}});
  canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/860,r.height/590);routeTarget={x:Math.max(0,Math.min(W,cam.x+(e.clientX-r.left)/scale)),y:Math.max(0,Math.min(H,cam.y+(e.clientY-r.top)/scale))}});
