  $('caseFileBtn').onclick=()=>caseFile('overview');$('menuBtn').onclick=()=>caseFile('saves');$('notebookBtn').onclick=notesModal;$('restBtn').onclick=rest;$('saveBtn').onclick=()=>caseFile('saves');$('soundBtn').onclick=toggleSound;
  document.querySelectorAll('.mobile-nav [data-panel]').forEach(b=>b.onclick=()=>{if(b.dataset.panel==='notes')notesModal();else if(b.dataset.panel==='case')caseFile('overview');else caseFile('overview')});
  updateUI();
})();

