   function dinerModal(){const talked=S.interviews.jonah;openModal('The Lantern Diner','OLD HARBOR · LAST CALL',`<p>Fluorescent light pools across empty booths. A cook wipes the same clean counter over and over. He watches you in the mirror before you speak.</p><div class="dialogue-line">“I told the patrol what I remember. I don’t want to be in the paper.”</div>${talked?'<p class="subtle">Jonah recognizes you. His account is preserved; he is more nervous now that the story is circulating.</p>':''}`,[{label:talked?'ASK ABOUT THE VOICE AGAIN':'ASK WHAT HE SAW',run:()=>{S.interviews.jonah=(S.interviews.jonah||0)+1;S.public++;if(!S.evidence.includes('witness'))addEvidence('witness');S.player.stress=Math.min(100,S.player.stress+3);log('Jonah Pike interviewed','The witness recalled a calm voice asking about the tower latch. Clove and wet wool. He is uncertain of the hour.');advance(24,'interview');openModal('A witness statement','INTERVIEW · JONAH PIKE',`<p>${talked?'On the second telling Jonah changes one detail:':'Jonah rubs his thumb along the edge of a coffee mug.'} “The voice wasn’t shouting. Asked about the tower door. Like they already knew it stuck. I smelled clove, maybe. It was raining hard.”</p><p class="subtle">Reliability: partial. His timeline is consistent with the dispatch window, but he admits he was closing his eyes between orders.</p><div class="statusline">STATEMENT RECORDED · DO NOT TREAT SCENT AS IDENTIFICATION</div>`,[{label:'THANK HIM',run:closeModal},{label:'PRESS HIM ON THE TIME',run:()=>{S.player.stress+=5;S.interviews.jonah=(S.interviews.jonah||0)+1;log('Witness pressured','Jonah withdrew certainty about the time. The core account remains.');toast('JONAH WITHDRAWS TIME ESTIMATE');closeModal()}}])}},{label:'BUY COFFEE · REST',run:()=>{S.player.fatigue=Math.max(0,S.player.fatigue-15);S.player.stress=Math.max(0,S.player.stress-5);advance(20);toast('COFFEE · A MOMENT OF QUIET');closeModal()}},{label:'LEAVE',run:closeModal}])}
-  function churchModal(){const actions=[];if(!S.evidence.includes('ledger'))actions.push({label:'REQUEST ACCESS TO HYMN LEDGER',kind:'primary',run:()=>{const silasSeen=!!S.interviews.silas;S.sect++;addEvidence('ledger');S.interviews.silas=(S.interviews.silas||0)+1;advance(35,'church');log('Silas Crowe interviewed','The archivist says the Ninth Verse was a teaching metaphor, but his initials appear beside the annotation.');openModal('Silas Crowe','PARISH ARCHIVIST · RECORDED INTERVIEW',`<div class="person-details"><span class="person-avatar avatar-one">SC</span><div><h3>Silas Crowe</h3><small>PARISH ARCHIVIST · 52 · RESIDENT 19 YEARS</small></div></div><div class="dialogue-line">“It’s an old hymn, Detective. People write in margins. The ninth verse is a warning against pride, not a prophecy.”</div><p>He offers the ledger without hesitation, then asks whether police intend to search the parish. He smells faintly of clove. You cannot tell whether this is meaningful or ordinary.</p><div class="statusline">INTERVIEW ${silasSeen?'UPDATED':'RECORDED'} · NO PROBABLE CAUSE ESTABLISHED</div>`,[{label:'ASK ABOUT HIS INITIALS',run:()=>{S.interviews.silas=(S.interviews.silas||0)+1;S.killerrisk+=4;S.player.stress+=4;log('Crowe questioned about the ledger','He says he catalogued the volume years ago. He is calm, but asks who else has seen the margin.');toast('CROWE KNOWS YOU HAVE THE LEDGER');closeModal()}},{label:'END INTERVIEW',run:closeModal}])}});if(!S.evidence.includes('register'))actions.push({label:'SEARCH PUBLIC CATALOG',run:()=>{addEvidence('register');S.sect++;advance(18);openModal('The choir register','PARISH ARCHIVE · CATALOG ENTRY',`<p>A ledger sign-out card shows Silas Crowe borrowed the restricted choir register four weeks ago. The book has not been returned. The parish secretary says the older volumes are sometimes used for restoration.</p><span class="tag unverified">LEAD · OBTAIN ORIGINAL REGISTER BEFORE CONCLUSION</span>`,[{label:'RETURN TO ARCHIVE',run:closeModal}])}});actions.push({label:'EXAMINE THE NAVE',run:()=>{S.player.stress=Math.min(100,S.player.stress+8);advance(15);openModal('A silence between bells','ST. ORAN · NAVE',`<p>The last rows are damp though the roof is sound. For one breath, the stained glass seems to show a figure standing behind you. When you turn, only the empty aisle remains.</p><p class="subtle">Stress rose. The experience may be exhaustion, suggestion, or something you cannot verify.</p>`,[{label:'COLLECT YOURSELF',run:()=>{S.player.stress=Math.max(0,S.player.stress-4);closeModal()}}])});actions.push({label:'LEAVE PARISH',run:closeModal});openModal('St. Oran Parish','PARISH HALL · FOUNDED 1891',`<p>Warm candlelight and rain-dark coats. The parish is open for evening prayer. A volunteer tells you the bell has been kept silent since the storm, then corrects herself: “Except the one time.”</p><div class="statusline">SECT LEAD · THE LANTERN OF THE NINTH DAWN</div>`,actions)}
+  function churchModal(){const actions=[];if(!S.evidence.includes('ledger'))actions.push({label:'REQUEST ACCESS TO HYMN LEDGER',kind:'primary',run:()=>{const silasSeen=!!S.interviews.silas;S.sect++;addEvidence('ledger');S.interviews.silas=(S.interviews.silas||0)+1;advance(35,'church');log('Silas Crowe interviewed','The archivist says the Ninth Verse was a teaching metaphor, but his initials appear beside the annotation.');openModal('Silas Crowe','PARISH ARCHIVIST · RECORDED INTERVIEW',`<div class="person-details"><span class="person-avatar avatar-one">SC</span><div><h3>Silas Crowe</h3><small>PARISH ARCHIVIST · 52 · RESIDENT 19 YEARS</small></div></div><div class="dialogue-line">“It’s an old hymn, Detective. People write in margins. The ninth verse is a warning against pride, not a prophecy.”</div><p>He offers the ledger without hesitation, then asks whether police intend to search the parish. He smells faintly of clove. You cannot tell whether this is meaningful or ordinary.</p><div class="statusline">INTERVIEW ${silasSeen?'UPDATED':'RECORDED'} · NO PROBABLE CAUSE ESTABLISHED</div>`,[{label:'ASK ABOUT HIS INITIALS',run:()=>{S.interviews.silas=(S.interviews.silas||0)+1;S.killerrisk+=4;S.player.stress+=4;log('Crowe questioned about the ledger','He says he catalogued the volume years ago. He is calm, but asks who else has seen the margin.');toast('CROWE KNOWS YOU HAVE THE LEDGER');closeModal()}},{label:'END INTERVIEW',run:closeModal}])}});if(!S.evidence.includes('register'))actions.push({label:'SEARCH PUBLIC CATALOG',run:()=>{addEvidence('register');S.sect++;advance(18);openModal('The choir register','PARISH ARCHIVE · CATALOG ENTRY',`<p>A ledger sign-out card shows Silas Crowe borrowed the restricted choir register four weeks ago. The book has not been returned. The parish secretary says the older volumes are sometimes used for restoration.</p><span class="tag unverified">LEAD · OBTAIN ORIGINAL REGISTER BEFORE CONCLUSION</span>`,[{label:'RETURN TO ARCHIVE',run:closeModal}])}});actions.push({label:'EXAMINE THE NAVE',run:()=>{S.player.stress=Math.min(100,S.player.stress+8);advance(15);openModal('A silence between bells','ST. ORAN · NAVE',`<p>The last rows are damp though the roof is sound. For one breath, the stained glass seems to show a figure standing behind you. When you turn, only the empty aisle remains.</p><p class="subtle">Stress rose. The experience may be exhaustion, suggestion, or something you cannot verify.</p>`,[{label:'COLLECT YOURSELF',run:()=>{S.player.stress=Math.max(0,S.player.stress-4);closeModal()}}])}});actions.push({label:'LEAVE PARISH',run:closeModal});openModal('St. Oran Parish','PARISH HALL · FOUNDED 1891',`<p>Warm candlelight and rain-dark coats. The parish is open for evening prayer. A volunteer tells you the bell has been kept silent since the storm, then corrects herself: “Except the one time.”</p><div class="statusline">SECT LEAD · THE LANTERN OF THE NINTH DAWN</div>`,actions)}

   function precinctModal(){
     const enough=S.evidence.length>=6&&['ledger','register','witness','autopsy'].every(x=>S.evidence.includes(x))&&S.interviews.silas;
     const actions=[{label:'PIN EVIDENCE TO THE BOARD',run:()=>{S.flags.boardReviewed=true;log('Evidence reviewed at the precinct','The scene mark, witness account, parish records, and medical window are compared. Clove and wool remain suggestive, not identifying.');advance(20,'analysis');openModal('The case board','MAJOR CRIMES · ANALYSIS',`<p>The Ninth Verse predates the current deaths by decades. The token links the scene to parish attendance, but not to a killer. Jonah’s account places an unknown person near the tower; the medical estimate narrows the window.</p><div class="statusline">${enough?'THE EVIDENCE SUPPORTS A NARROW, SEARCHABLE THEORY.':'MORE INDEPENDENT CORROBORATION IS NEEDED BEFORE A WARRANT.'}</div><p class="subtle">A theory is not proof. Do not treat scent, ritual staging, or rumor as identification.</p>`,[{label:'BACK TO PRECINCT',run:closeModal}])}}];

