#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
/usr/bin/time -p node "${RUNTIME_DIR:?}/scripts/default-capture.mjs"

(() => {
  'use strict';
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const W = 1600, H = 1100, $ = id => document.getElementById(id);
  const places = [
    {id:'scene',name:"ST. ORAN'S BELL TOWER",sub:'CRIME SCENE · CORDON ACTIVE',x:410,y:365,color:'#6b5144',kind:'scene',icon:'✳'},
    {id:'diner',name:'THE LANTERN DINER',sub:'WITNESS LAST SEEN HERE',x:740,y:535,color:'#76634d',kind:'diner',icon:'▰'},
    {id:'church',name:'ST. ORAN PARISH',sub:'PARISH ARCHIVES · OPEN',x:700,y:250,color:'#746d5c',kind:'church',icon:'✝'},
    {id:'precinct',name:'BELLWETHER PRECINCT',sub:'MAJOR CRIMES · YOUR OFFICE',x:1085,y:350,color:'#51605a',kind:'precinct',icon:'▥'},
    {id:'morgue',name:'COUNTY MEDICAL EXAMINER',sub:'AUTOPSY WING · RESTRICTED',x:1160,y:685,color:'#53615a',kind:'morgue',icon:'＋'},
    {id:'cemetery',name:'ASHGROVE CEMETERY',sub:'NORTH GATE · 24 HOURS',x:260,y:750,color:'#596450',kind:'cemetery',icon:'†'},
    {id:'archive',name:'OLD COUNTY RECORDS',sub:'BASEMENT STACKS',x:900,y:800,color:'#625c50',kind:'archive',icon:'▤'},
    {id:'apartment',name:'VANE STREET FLATS',sub:'MISSING PERSONS ADDRESS',x:1330,y:510,color:'#69584f',kind:'apartment',icon:'▥'},
    {id:'forest',name:'BLACKWATER TREE LINE',sub:'COUNTY ROAD 9 · NO LIGHTING',x:360,y:990,color:'#465443',kind:'forest',icon:'♧'},
    {id:'bar',name:'THE MERCY ROOM',sub:'CLOSED FOR THE NIGHT',x:950,y:170,color:'#594c48',kind:'bar',icon:'◒'},
    {id:'hospital',name:'BELLWETHER GENERAL',sub:'EMERGENCY DEPARTMENT',x:1400,y:850,color:'#52605e',kind:'hospital',icon:'＋'}
  ];
  const seed = n => {let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
  const npcNames=['Mara Venn','Silas Crowe','Ruth Bell','Jonah Pike','Elise Ward','Tom Arlen','Nora Vale','Caleb Dunn','Miriam Holt','Edwin Shaw','June Mercer','Isaac Reed','Lena Park','Peter Moss','Ada Finch','Gideon Frost'];
  const npcs=Array.from({length:42},(_,i)=>({id:i,name:npcNames[i%npcNames.length]+(i>=16?' '+String.fromCharCode(65+i%26):''),x:90+seed(i+4)*1420,y:90+seed(i+90)*920,home:places[Math.floor(seed(i+500)*places.length)].id,mood:seed(i+100)*2-1,phase:seed(i+120)*Math.PI*2,speed:.15+seed(i+40)*.28,important:i===1||i===2||i===3,alive:true}));
  const defaults=()=>({version:1,day:1,minute:21*60+14,weather:'COLD RAIN',player:{x:455,y:385,health:94,stress:28,fatigue:18},evidence:[],notes:'',events:[{day:1,time:'21:14',title:'A bell after the storm',text:'Patrol found Mara Venn beneath the bell tower at St. Oran’s. The scene was secured at 20:46.'}],interviews:{},visited:{},warrant:false,arrested:false,sect:0,public:0,adapt:0,visits:{},killerrisk:18, killerMood:'observant',killerRoutine:'parish',randomSeed:Math.floor(Math.random()*1e8),flags:{},npcMemory:{},theories:[],heardBell:true,ending:null});
  let S=loadAuto()||defaults(), cam={x:0,y:0}, keys={},lastTick=performance.now(),acc=0,toastTimer,modalPage='overview',activePlace=null,moveEnabled=true,wasMoving=false,ambientOn=false,routeTarget=null;
  const evidenceData={
    sigil:{name:'The split halo',kind:'VERIFIED · SCENE',desc:'A hand-drawn mark in ash beneath the bell stairs. The upper arc is deliberately broken. Not a standard parish symbol.'},
    fiber:{name:'Gray wool fiber',kind:'LAB · TRACE',desc:'A coarse gray wool fiber snagged on a nail at shoulder height. Consistent with a heavy coat; common in town, but not the scene custodians’ uniforms.'},
    token:{name:'Brass choir token',kind:'VERIFIED · SCENE',desc:'A tarnished token stamped with nine small notches. Parish ledgers call these “attendance counters”; the ninth notch is newer.'},
    witness:{name:'A voice at 9:13',kind:'WITNESS · UNCORROBORATED',desc:'Diner cook Jonah Pike remembers a calm voice asking whether the tower door still sticks. He recalls a smell of clove and wet wool.'},
    ledger:{name:'The Ninth Verse',kind:'DOCUMENT · VERIFIED',desc:'A marginal note in a 1938 hymn ledger: “When the bell speaks without a hand, the keeper must answer.” Initials S.C. appear in the same ink.'},
    autopsy:{name:'Estimated time of death',kind:'FORENSIC · VERIFIED',desc:'Dr. Vale places death between 19:40 and 20:20. The staged scene was assembled later; the arrangement is not a reliable signature.'},
    register:{name:'Restricted choir register',kind:'DOCUMENT · LEAD',desc:'An old roll lists nine “night keepers.” One line was cut out; the ledger was signed out under Silas Crowe’s credentials last month.'},
    letter:{name:'Unsent letter',kind:'PERSONAL · UNVERIFIED',desc:'A letter in Mara’s flat mentions “the ones who wear ordinary faces” and asks someone to stop coming to the archives.'}
  };
  function loadAuto(){try{return JSON.parse(localStorage.getItem('town-autosave')||'null')}catch{return null}}
  function save(slot='auto'){try{localStorage.setItem('town-'+slot,JSON.stringify(S)); if(slot!=='auto')toast(`CASE FILE SAVED · SLOT ${slot.replace('slot','')}`); else toast('AUTOSAVE COMPLETE')}catch{toast('SAVE FAILED · STORAGE UNAVAILABLE')}}
  function addEvidence(id){if(S.evidence.includes(id)){toast('ALREADY LOGGED · CHAIN OF CUSTODY INTACT');return false}S.evidence.push(id);S.events.unshift({day:S.day,time:clock(),title:`Evidence logged: ${evidenceData[id].name}`,text:evidenceData[id].desc});updateUI();save('auto');return true}
  function log(title,text){S.events.unshift({day:S.day,time:clock(),title,text});S.events=S.events.slice(0,40)}
  function clock(){return String(Math.floor(S.minute/60)%24).padStart(2,'0')+':'+String(S.minute%60).padStart(2,'0')}
  function advance(mins,reason=''){S.minute+=mins;while(S.minute>=1440){S.minute-=1440;S.day++;S.player.fatigue=Math.min(100,S.player.fatigue+10);log('A town wakes to another day','The streets carry last night’s rumors forward.');}S.player.fatigue=Math.min(100,S.player.fatigue+mins*.022);S.player.stress=Math.min(100,S.player.stress+mins*.003);if(mins>25)killerThink(reason);if(Math.random()<.14){const lines=['Dispatch reports another power flicker near the old parish.','A reporter has been asking about the Venn case at the diner.','The rain has washed chalk from the courthouse steps.','Someone left fresh flowers outside the precinct.','A church bell rings once, though no service is listed.','A neighborhood watch group is circulating a false description.'];$('townPulse').textContent=lines[Math.floor(Math.random()*lines.length)];$('pulseSource').textContent='BELLWETHER DISPATCH · JUST NOW'}updateUI();save('auto')}
  function killerThink(reason){S.adapt++;const focus=Object.entries(S.visits).sort((a,b)=>b[1]-a[1])[0];if(S.evidence.length>=3)S.killerrisk=Math.min(94,S.killerrisk+9);if(focus&&focus[1]>=3&&focus[0]==='church'){S.killerRoutine='changed';S.killerMood='uneasy';}else if(S.public>1){S.killerMood='paranoid';}else if(Math.random()<.35){S.killerMood='confident';}if(S.adapt%2===0){log('Unseen adjustments',S.killerMood==='uneasy'?'A familiar face has stopped attending evening services. The reason is not yet known.':S.killerMood==='paranoid'?'A source at the parish says the archivist has been asking what the police know.': 'The town continues its ordinary routines around the investigation.');}if(S.killerrisk>60&&S.adapt%3===0){S.flags.killerMistake=true;log('A routine changes','A parish volunteer reports that someone has been removing entries from the choir register.');}}
  function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  function updateUI(){ $('clockText').textContent=clock();$('dayText').textContent='DAY '+String(S.day).padStart(2,'0');$('dayCount').textContent=String(S.day).padStart(2,'0');$('evidenceCount').textContent=S.evidence.length;$('healthValue').textContent=Math.round(S.player.health);$('stressValue').textContent=Math.max(0,100-Math.round(S.player.stress));$('fatigueValue').textContent=Math.round(S.player.fatigue);$('healthMeter').style.width=S.player.health+'%';$('stressMeter').style.width=(100-S.player.stress)+'%';$('fatigueMeter').style.width=S.player.fatigue+'%';$('objectiveText').textContent=objective();$('rainLayer').style.opacity=S.weather==='CLEAR'?.04:.32;$('weatherText').textContent=S.weather;const act=activeNear();$('interactPrompt').classList.toggle('hidden',!act);if(act)$('promptText').textContent=act.name;$('districtLabel').textContent=(act?act.name.split(' · ')[0]:'OLD HARBOR')+' · '+(S.minute<360||S.minute>1170?'NIGHT':'DAY');}
  function objective(){if(!S.evidence.includes('sigil'))return 'Return to the first scene';if(!S.evidence.includes('witness'))return 'Find the witness at The Lantern';if(!S.evidence.includes('ledger'))return 'Ask the parish about the ninth verse';if(!S.evidence.includes('autopsy'))return 'Request the medical examiner’s report';if(S.evidence.length<5)return 'Connect the clues at the precinct';if(!S.warrant)return 'Build probable cause and request a warrant';if(!S.arrested)return 'Confront Silas Crowe';return 'Decide what the truth means';}
  function activeNear(){let best=null,d0=94;for(const p of places){const d=Math.hypot(p.x-S.player.x,p.y-S.player.y);if(d<d0){best=p;d0=d}}return best}
  function fitCanvas(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',fitCanvas);fitCanvas();
  function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);const scale=Math.min(w/860,h/590),sx=w/scale,sy=h/scale;cam.x=Math.max(0,Math.min(W-sx,S.player.x-sx/2));cam.y=Math.max(0,Math.min(H-sy,S.player.y-sy/2));ctx.save();ctx.scale(scale,scale);ctx.translate(-cam.x,-cam.y);drawTown();ctx.restore();requestAnimationFrame(draw)}
  function drawTown(){ctx.fillStyle='#28332e';ctx.fillRect(0,0,W,H); // district ground
    for(let i=0;i<70;i++){let x=seed(i+701)*W,y=seed(i+803)*H;ctx.fillStyle=['#354036','#303b34','#343c36','#29352f'][i%4];ctx.beginPath();ctx.ellipse(x,y,25+seed(i)*65,16+seed(i+21)*44,seed(i+31)*3,0,Math.PI*2);ctx.fill()}
    // road network
    ctx.fillStyle='#333936';[[0,120,1600,75],[0,430,1600,86],[0,735,1600,82],[220,0,70,1100],[540,0,66,1100],[850,0,76,1100],[1220,0,74,1100]].forEach(r=>ctx.fillRect(...r));
    ctx.strokeStyle='#7e806f2c';ctx.lineWidth=2;ctx.setLineDash([14,18]);[[0,158,1600,158],[0,471,1600,471],[0,775,1600,775],[253,0,253,1100],[572,0,572,1100],[887,0,887,1100],[1257,0,1257,1100]].forEach(r=>{ctx.beginPath();ctx.moveTo(r[0],r[1]);ctx.lineTo(r[2],r[3]);ctx.stroke()});ctx.setLineDash([]);
    // buildings arranged in blocks
    for(let row=0;row<5;row++)for(let col=0;col<7;col++){const x=60+col*215+(row%2)*30,y=35+row*210;if(x>W-150||y>H-115)continue;if(places.some(p=>Math.abs(p.x-x)<112&&Math.abs(p.y-y)<100))continue;building(x,y,112,81,['#4a5049','#4c4a42','#3e4b46','#514943'][(row*7+col)%4],false)}
    // parks and cemetery
    ctx.fillStyle='#354535';ctx.fillRect(55,665,260,235);ctx.fillRect(300,920,580,180);ctx.fillStyle='#a5a18e';ctx.font='11px monospace';ctx.fillText('ASHGROVE COMMON',75,690);for(let i=0;i<23;i++){tree(80+seed(i+44)*210,715+seed(i+14)*165,seed(i+8)*.6+.7)}
    for(let i=0;i<8;i++){const x=335+i*57;ctx.fillStyle='#827e70';ctx.fillRect(x,970,7,18);ctx.fillRect(x+17,1005,7,18)}
    // small street lamps
    for(const [x,y] of [[254,180],[574,300],[890,485],[1257,650],[540,670],[850,130],[300,480],[1120,770]]){ctx.fillStyle='#bea779';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#cbb27b12';ctx.beginPath();ctx.arc(x,y,42,0,Math.PI*2);ctx.fill()}
    places.forEach(p=>drawPlace(p));
    // wandering residents
    const t=performance.now()/1000;for(const n of npcs){if(!n.alive)continue;let nx=n.x+Math.sin(t*.12+n.phase)*32,ny=n.y+Math.cos(t*.09+n.phase)*18;const p=places.find(x=>x.id===n.home);if(p&&n.important){nx=p.x+Math.sin(t*.08+n.phase)*18;ny=p.y+Math.cos(t*.07+n.phase)*12}ctx.fillStyle=n.important?'#c5aa7d':'#7f9188';ctx.beginPath();ctx.arc(nx,ny,n.important?4:2.6,0,Math.PI*2);ctx.fill();if(n.important){ctx.fillStyle='#111';ctx.fillRect(nx-2,ny+3,4,8)}}
    // player
    const px=S.player.x,py=S.player.y;ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(px,py+13,11,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5c4a2';ctx.beginPath();ctx.arc(px,py,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222a27';ctx.beginPath();ctx.moveTo(px-7,py+5);ctx.lineTo(px+7,py+5);ctx.lineTo(px+9,py+22);ctx.lineTo(px-9,py+22);ctx.fill();ctx.strokeStyle='#ddc38e';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(px,py-2);ctx.lineTo(px,py-13);ctx.stroke();
    // subtle rain marks
