  function frame(){const now=performance.now(),dt=Math.min(.05,(now-lastTick)/1000);lastTick=now;acc+=dt;if(acc>1){acc=0;S.minute++;if(S.minute>=1440){S.minute=0;S.day++;S.player.fatigue=Math.min(100,S.player.fatigue+5);log('Dawn over Bellwether','A new day begins. The investigation moves with it.')}if(Math.random()<.025)S.player.stress=Math.min(100,S.player.stress+.25);updateUI();if(Math.random()<.015)save('auto')}
